from __future__ import annotations

from dataclasses import dataclass
from io import BytesIO
from pathlib import Path

from docx import Document
from pypdf import PdfReader


SUPPORTED_EXTENSIONS = {".pdf", ".docx", ".txt", ".md", ".markdown"}


@dataclass(frozen=True)
class ExtractedDocument:
    filename: str
    extension: str
    text: str
    word_count: int
    char_count: int


def extract_document(filename: str, content: bytes) -> ExtractedDocument:
    extension = Path(filename).suffix.lower()
    if extension not in SUPPORTED_EXTENSIONS:
        supported = ", ".join(sorted(SUPPORTED_EXTENSIONS))
        raise ValueError(f"Unsupported file type '{extension}'. Supported: {supported}.")

    if extension == ".pdf":
        text = extract_pdf(content)
    elif extension == ".docx":
        text = extract_docx(content)
    else:
        text = decode_text(content)

    cleaned = normalize_text(text)
    return ExtractedDocument(
        filename=filename,
        extension=extension,
        text=cleaned,
        word_count=len(cleaned.split()),
        char_count=len(cleaned),
    )


def extract_pdf(content: bytes) -> str:
    reader = PdfReader(BytesIO(content))
    pages = [page.extract_text() or "" for page in reader.pages]
    return "\n\n".join(pages)


def extract_docx(content: bytes) -> str:
    document = Document(BytesIO(content))
    paragraphs = [paragraph.text for paragraph in document.paragraphs if paragraph.text.strip()]
    table_lines: list[str] = []
    for table in document.tables:
        for row in table.rows:
            cells = [cell.text.strip() for cell in row.cells if cell.text.strip()]
            if cells:
                table_lines.append(" | ".join(cells))
    return "\n\n".join(paragraphs + table_lines)


def decode_text(content: bytes) -> str:
    for encoding in ("utf-8-sig", "utf-8", "gb18030", "latin-1"):
        try:
            return content.decode(encoding)
        except UnicodeDecodeError:
            continue
    return content.decode("utf-8", errors="replace")


def normalize_text(text: str) -> str:
    lines = [line.rstrip() for line in text.replace("\r\n", "\n").replace("\r", "\n").split("\n")]
    collapsed: list[str] = []
    blank = False
    for line in lines:
        if not line.strip():
            if not blank:
                collapsed.append("")
            blank = True
            continue
        collapsed.append(line.strip())
        blank = False
    return "\n".join(collapsed).strip()

from __future__ import annotations

from pydantic import BaseModel, Field

FONT_FAMILIES: dict[str, dict[str, str]] = {
    "times": {"label": "Times New Roman", "docx": "Times New Roman", "pdf": "times"},
    "simsun": {"label": "宋体", "docx": "宋体", "pdf": "simsun"},
    "yahei": {"label": "微软雅黑", "docx": "微软雅黑", "pdf": "yahei"},
    "arial": {"label": "Arial", "docx": "Arial", "pdf": "arial"},
}


class ExportFormatOptions(BaseModel):
    font_family: str = Field(default="times")
    font_size: int = Field(default=12, ge=9, le=18)
    line_spacing: float = Field(default=1.5, ge=1.0, le=3.0)
    margin_inches: float = Field(default=1.25, ge=0.5, le=2.0)

    def resolved_family(self) -> dict[str, str]:
        return FONT_FAMILIES.get(self.font_family, FONT_FAMILIES["times"])

from __future__ import annotations

import os
import platform
import subprocess
from pathlib import Path


def open_in_file_manager(path: str) -> str:
    """Open a folder (or the parent of a file) in the system file manager."""
    target = Path(path).expanduser().resolve()
    folder = target if target.is_dir() else target.parent
    if not folder.exists():
        raise FileNotFoundError(f"路径不存在: {folder}")

    system = platform.system()
    if system == "Windows":
        os.startfile(folder)  # type: ignore[attr-defined]
    elif system == "Darwin":
        subprocess.run(["open", str(folder)], check=True)
    else:
        subprocess.run(["xdg-open", str(folder)], check=True)
    return str(folder)

