from starlette.requests import Request

DEEPSEEK_DEFAULTS = {
    "base_url": "https://api.deepseek.com/v1",
    "model": "deepseek-chat",
}


def normalize_base_url(url: str) -> str:
    """Ensure OpenAI-compatible base URL ends with /v1."""
    cleaned = (url or "").strip().rstrip("/")
    if not cleaned:
        return DEEPSEEK_DEFAULTS["base_url"]
    if cleaned.endswith("/v1"):
        return cleaned
    if cleaned.endswith("/chat/completions"):
        return cleaned[: -len("/chat/completions")].rstrip("/")
    return f"{cleaned}/v1"


def tavily_key_from_request(request: Request) -> str:
    return (request.headers.get("x-tavily-key") or "").strip()


def settings_from_request(request: Request) -> Settings:
    """Use per-request LLM headers only — never fall back to server .env API key."""
    base = get_settings()
    api_key = (request.headers.get("x-api-key") or "").strip()
    base_url = normalize_base_url((request.headers.get("x-base-url") or "").strip() or base.openai_base_url)
    model = (request.headers.get("x-model") or "").strip() or base.openai_model
    return base.model_copy(
        update={
            "openai_api_key": api_key,
            "openai_base_url": base_url,
            "openai_model": model,
        }
    )


def client_from_settings(settings: Settings) -> OpenAICompatibleClient:
    normalized = settings.model_copy(update={"openai_base_url": normalize_base_url(settings.openai_base_url)})
    return OpenAICompatibleClient(settings=normalized)


def client_from_request(request: Request) -> OpenAICompatibleClient:
    return client_from_settings(settings_from_request(request))

from __future__ import annotations

import re
from urllib.parse import quote_plus

from academic_agent.models import Paper, SourceName

_CJK = re.compile(r"[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]")
_LATIN_RATIO = re.compile(r"[A-Za-z]")


def is_english_scholarly(paper: Paper) -> bool:
    title = paper.title or ""
    if _CJK.search(title):
        return False
    if _CJK.search(paper.abstract or ""):
        return False
    letters = len(_LATIN_RATIO.findall(title))
    if letters < max(8, len(title) * 0.45):
        return False
    if not paper.abstract or len(paper.abstract.strip()) < 60:
        return False
    return True


def paper_link(paper: Paper) -> str:
    if paper.doi:
        return f"https://doi.org/{paper.doi}"
    if paper.url:
        return str(paper.url)
    if paper.arxiv_id:
        return f"https://arxiv.org/abs/{paper.arxiv_id}"
    return scholar_url(paper)


def scholar_url(paper: Paper) -> str:
    q = quote_plus(paper.title)
    if paper.authors:
        q = quote_plus(f"{paper.title} {paper.authors[0]}")
    return f"https://scholar.google.com/scholar?hl=en&q={q}"


def quality_rank(paper: Paper) -> int:
    score = 0
    if paper.source == SourceName.SEMANTIC_SCHOLAR:
        score += 12
    if paper.source == SourceName.OPENALEX:
        score += 8
    if paper.doi:
        score += 10
    if paper.abstract:
        score += 6
    cites = paper.citation_count or 0
    score += min(cites, 500) // 5
    if paper.venue:
        score += 3
    return score


def is_scholarly_source(paper: Paper) -> bool:
    return paper.source in {
        SourceName.SEMANTIC_SCHOLAR,
        SourceName.OPENALEX,
        SourceName.CROSSREF,
        SourceName.ARXIV,
    }


def filter_scholar_quality(papers: list[Paper], *, min_citations: int = 5) -> list[Paper]:
    filtered: list[Paper] = []
    for p in papers:
        if not is_scholarly_source(p):
            continue
        if not is_english_scholarly(p):
            continue
        cites = p.citation_count or 0
        if cites < min_citations and p.source not in {SourceName.ARXIV, SourceName.SEMANTIC_SCHOLAR}:
            continue
        if p.source == SourceName.CROSSREF and cites < 3 and not p.doi:
            continue
        filtered.append(p)
    filtered.sort(key=quality_rank, reverse=True)
    return filtered

from __future__ import annotations

import re

_CJK = re.compile(r"[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]")


def topic_needs_english_queries(topic: str) -> bool:
    return bool(_CJK.search(topic))


def english_scholar_queries(topic: str, *, llm=None) -> list[str]:
    """Build English search phrases for scholarly APIs (GS has no public API)."""
    topic = topic.strip()
    if not topic:
        return []
    if not topic_needs_english_queries(topic):
        return _dedupe_queries([topic])

    if llm is not None:
        try:
            raw = llm.chat(
                [
                    {
                        "role": "system",
                        "content": (
                            "Translate academic topics into 3 concise English Google Scholar search queries. "
                            "Return one query per line, no numbering, no Chinese."
                        ),
                    },
                    {"role": "user", "content": f"Topic: {topic}"},
                ],
                temperature=0.1,
                max_tokens=180,
            )
            lines = [ln.strip(" -•\t") for ln in raw.splitlines() if ln.strip()]
            cleaned = [ln for ln in lines if ln and not _CJK.search(ln)]
            if cleaned:
                return _dedupe_queries(cleaned[:4])
        except Exception:
            pass

    return _dedupe_queries([topic, f"{topic} systematic review", f"{topic} empirical study"])


def _dedupe_queries(queries: list[str]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for q in queries:
        key = re.sub(r"\W+", " ", q.lower()).strip()
        if not key or key in seen:
            continue
        seen.add(key)
        out.append(q.strip())
    return out

from __future__ import annotations

import re
import xml.etree.ElementTree as ET
from collections.abc import Iterable
from collections.abc import Callable
from urllib.parse import quote_plus

import httpx

from academic_agent.config import Settings, get_settings
from academic_agent.http_utils import make_http_client
from academic_agent.models import Paper, SourceName
from academic_agent.scholar_quality import filter_scholar_quality, is_scholarly_source
from academic_agent.scholar_search import search_scholar_multi, search_scholar_primary
from academic_agent.tavily_search import search_tavily


def _clean_text(value: str | None) -> str | None:
    if not value:
        return None
    return re.sub(r"\s+", " ", value).strip()


def _author_names(items: Iterable[dict]) -> list[str]:
    names: list[str] = []
    for item in items:
        name = item.get("display_name") or item.get("name")
        if name:
            names.append(str(name))
    return names


class AcademicSearcher:
    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings or get_settings()

    def search(
        self,
        query: str,
        *,
        limit: int = 10,
        tavily_key: str = "",
        web_search: bool = True,
        extra_queries: list[str] | None = None,
    ) -> list[Paper]:
        queries = [query.strip()]
        if extra_queries:
            queries.extend(q.strip() for q in extra_queries if q.strip())
        results: list[Paper] = (
            search_scholar_multi(queries, limit=max(limit, 15))
            if len(queries) > 1
            else list(search_scholar_primary(query, limit=max(limit, 15)))
        )
        if len(results) < limit:
            per_source = max(4, min(limit, 15))
            with make_http_client(timeout=30.0) as client:
                for fetcher in (self._semantic_scholar, self._openalex):
                    results.extend(self._safe_fetch(fetcher, client, query, per_source))
        results = dedupe_papers(results)
        results = [p for p in results if is_scholarly_source(p)]
        results = filter_scholar_quality(results, min_citations=3)
        if len(results) < limit:
            relaxed = filter_scholar_quality(dedupe_papers(results), min_citations=1)
            results = relaxed[:limit]
        if web_search and tavily_key and len(results) < max(4, limit // 3):
            # Tavily only fills gaps; never used as primary citations.
            tavily_hits = search_tavily(query, api_key=tavily_key, limit=3)
            results = dedupe_papers(results + tavily_hits)
            results = [p for p in results if is_scholarly_source(p)] or results[:limit]
        return results[:limit]

    def by_doi(self, doi: str) -> Paper | None:
        doi = doi.strip().removeprefix("https://doi.org/")
        with make_http_client(timeout=30.0) as client:
            for fetcher in (self._crossref_doi, self._openalex_doi):
                try:
                    paper = fetcher(client, doi)
                except httpx.HTTPError:
                    paper = None
                if paper:
                    return paper
        return None

    def by_arxiv_id(self, arxiv_id: str) -> Paper | None:
        arxiv_id = arxiv_id.strip().removeprefix("arXiv:")
        url = f"https://export.arxiv.org/api/query?id_list={quote_plus(arxiv_id)}"
        with make_http_client(timeout=30.0) as client:
            response = client.get(url)
            if response.status_code >= 400:
                return None
            papers = self._parse_arxiv(response.text)
        return papers[0] if papers else None

    def _openalex(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        response = client.get(
            "https://api.openalex.org/works",
            params={
                "search": query,
                "per-page": limit,
                "filter": "language:en,cited_by_count:>5,type:article",
                "sort": "cited_by_count:desc",
            },
        )
        if response.status_code >= 400:
            return []
        return [self._openalex_work(item) for item in response.json().get("results", [])]

    @staticmethod
    def _safe_fetch(
        fetcher: Callable[[httpx.Client, str, int], list[Paper]],
        client: httpx.Client,
        query: str,
        limit: int,
    ) -> list[Paper]:
        try:
            return fetcher(client, query, limit)
        except (httpx.HTTPError, ET.ParseError):
            return []

    def _openalex_doi(self, client: httpx.Client, doi: str) -> Paper | None:
        response = client.get(f"https://api.openalex.org/works/https://doi.org/{doi}")
        if response.status_code >= 400:
            return None
        return self._openalex_work(response.json())

    def _openalex_work(self, item: dict) -> Paper:
        authorships = item.get("authorships") or []
        authors = [a.get("author", {}).get("display_name") for a in authorships]
        abstract = inverted_index_to_text(item.get("abstract_inverted_index"))
        primary_location = item.get("primary_location") or {}
        source = primary_location.get("source") or {}
        return Paper(
            title=_clean_text(item.get("title")) or "Untitled",
            authors=[a for a in authors if a],
            year=item.get("publication_year"),
            abstract=abstract,
            doi=(item.get("doi") or "").removeprefix("https://doi.org/") or None,
            url=item.get("id") or item.get("doi"),
            venue=source.get("display_name"),
            citation_count=item.get("cited_by_count"),
            source=SourceName.OPENALEX,
            source_id=item.get("id"),
            raw=item,
        )

    def _semantic_scholar(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        headers = {}
        if self.settings.semantic_scholar_api_key:
            headers["x-api-key"] = self.settings.semantic_scholar_api_key
        response = client.get(
            "https://api.semanticscholar.org/graph/v1/paper/search",
            params={
                "query": query,
                "limit": limit,
                "fields": "title,authors,year,abstract,venue,citationCount,externalIds,url",
            },
            headers=headers,
        )
        if response.status_code >= 400:
            return []
        papers: list[Paper] = []
        for item in response.json().get("data", []):
            external = item.get("externalIds") or {}
            papers.append(
                Paper(
                    title=_clean_text(item.get("title")) or "Untitled",
                    authors=_author_names(item.get("authors") or []),
                    year=item.get("year"),
                    abstract=_clean_text(item.get("abstract")),
                    doi=external.get("DOI"),
                    arxiv_id=external.get("ArXiv"),
                    url=item.get("url"),
                    venue=item.get("venue"),
                    citation_count=item.get("citationCount"),
                    source=SourceName.SEMANTIC_SCHOLAR,
                    source_id=item.get("paperId"),
                    raw=item,
                )
            )
        return papers

    def _crossref(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        response = client.get("https://api.crossref.org/works", params={"query": query, "rows": limit})
        if response.status_code >= 400:
            return []
        return [self._crossref_item(item) for item in response.json().get("message", {}).get("items", [])]

    def _crossref_doi(self, client: httpx.Client, doi: str) -> Paper | None:
        response = client.get(f"https://api.crossref.org/works/{quote_plus(doi)}")
        if response.status_code >= 400:
            return None
        item = response.json().get("message")
        return self._crossref_item(item) if item else None

    def _crossref_item(self, item: dict) -> Paper:
        authors = []
        for author in item.get("author") or []:
            given = author.get("given", "")
            family = author.get("family", "")
            name = " ".join(part for part in [given, family] if part).strip()
            if name:
                authors.append(name)
        year = None
        date_parts = (item.get("published-print") or item.get("published-online") or item.get("created") or {}).get(
            "date-parts"
        )
        if date_parts and date_parts[0]:
            year = date_parts[0][0]
        titles = item.get("title") or []
        containers = item.get("container-title") or []
        abstracts = item.get("abstract")
        return Paper(
            title=_clean_text(titles[0] if titles else None) or "Untitled",
            authors=authors,
            year=year,
            abstract=_clean_text(strip_tags(abstracts)),
            doi=item.get("DOI"),
            url=item.get("URL"),
            venue=containers[0] if containers else None,
            citation_count=item.get("is-referenced-by-count"),
            source=SourceName.CROSSREF,
            source_id=item.get("DOI"),
            raw=item,
        )

    def _arxiv(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        url = (
            "https://export.arxiv.org/api/query"
            f"?search_query=all:{quote_plus(query)}&start=0&max_results={limit}&sortBy=relevance"
        )
        response = client.get(url)
        if response.status_code >= 400:
            return []
        return self._parse_arxiv(response.text)

    @staticmethod
    def _parse_arxiv(xml_text: str) -> list[Paper]:
        ns = {"a": "http://www.w3.org/2005/Atom"}
        root = ET.fromstring(xml_text)
        papers: list[Paper] = []
        for entry in root.findall("a:entry", ns):
            entry_id = entry.findtext("a:id", default="", namespaces=ns)
            arxiv_id = entry_id.rsplit("/", 1)[-1] if entry_id else None
            authors = [node.findtext("a:name", default="", namespaces=ns) for node in entry.findall("a:author", ns)]
            published = entry.findtext("a:published", default="", namespaces=ns)
            doi_node = entry.find("{http://arxiv.org/schemas/atom}doi")
            doi = doi_node.text if doi_node is not None else None
            papers.append(
                Paper(
                    title=_clean_text(entry.findtext("a:title", default="", namespaces=ns)) or "Untitled",
                    authors=[a for a in authors if a],
                    year=int(published[:4]) if published[:4].isdigit() else None,
                    abstract=_clean_text(entry.findtext("a:summary", default="", namespaces=ns)),
                    doi=doi,
                    arxiv_id=arxiv_id,
                    url=entry_id,
                    source=SourceName.ARXIV,
                    source_id=arxiv_id,
                    raw={},
                )
            )
        return papers


def strip_tags(text: str | None) -> str | None:
    if not text:
        return None
    return re.sub(r"<[^>]+>", " ", text)


def inverted_index_to_text(index: dict[str, list[int]] | None) -> str | None:
    if not index:
        return None
    words: list[str | None] = [None] * (max(pos for positions in index.values() for pos in positions) + 1)
    for word, positions in index.items():
        for pos in positions:
            words[pos] = word
    return _clean_text(" ".join(word or "" for word in words))


def dedupe_papers(papers: list[Paper]) -> list[Paper]:
    index_by_key: dict[str, int] = {}
    unique: list[Paper] = []
    for paper in papers:
        key = paper.doi.lower() if paper.doi else normalize_title(paper.title)
        if key in index_by_key:
            current_index = index_by_key[key]
            if paper_quality_score(paper) > paper_quality_score(unique[current_index]):
                unique[current_index] = paper
            continue
        index_by_key[key] = len(unique)
        unique.append(paper)
    return unique


def paper_quality_score(paper: Paper) -> int:
    return (
        int(bool(paper.doi)) * 4
        + int(bool(paper.arxiv_id)) * 3
        + int(bool(paper.abstract)) * 2
        + int(bool(paper.url))
        + min(paper.citation_count or 0, 1000) // 100
    )


def normalize_title(title: str) -> str:
    return re.sub(r"\W+", "", title.lower())

/* Joeku — projects · modal params · split doc stream (no ES module — avoids load failures) */

function renderMarkdown(md) {
  if (!md) return "";
  const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const inline = (text) =>
    text
      .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>')
      .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      .replace(/\*(.+?)\*/g, "<em>$1</em>")
      .replace(/`([^`]+)`/g, "<code>$1</code>");
  const lines = md.split(/\r?\n/);
  const out = [];
  let inP = false;
  const closeP = () => {
    if (inP) {
      out.push("</p>");
      inP = false;
    }
  };
  for (const raw of lines) {
    const line = raw.trimEnd();
    if (!line.trim()) {
      closeP();
      continue;
    }
    if (line.startsWith("# ")) {
      closeP();
      out.push(`<h1>${inline(esc(line.slice(2)))}</h1>`);
      continue;
    }
    if (line.startsWith("## ")) {
      closeP();
      out.push(`<h2>${inline(esc(line.slice(3)))}</h2>`);
      continue;
    }
    if (line.startsWith("### ")) {
      closeP();
      out.push(`<h3>${inline(esc(line.slice(4)))}</h3>`);
      continue;
    }
    if (line.startsWith("- ") || line.startsWith("* ")) {
      closeP();
      out.push(`<li>${inline(esc(line.slice(2)))}</li>`);
      continue;
    }
    if (!inP) {
      out.push("<p>");
      inP = true;
    } else {
      out.push("<br/>");
    }
    out.push(inline(esc(line)));
  }
  closeP();
  return out.join("");
}

const STORAGE = {
  config: "joeku-llm-config",
  folder: "joeku-save-folder",
  perm: "joeku-local-perm",
  projects: "joeku-projects",
  currentProject: "joeku-current-project",
  tavily: "joeku-tavily-key",
  exportFormat: "joeku-export-format",
  activeJob: "joeku-active-job",
  docCollapsed: "joeku-doc-collapsed",
};

const state = {
  mode: "generate",
  loggedIn: false,
  config: { api_key: "", base_url: "https://api.deepseek.com/v1", model: "deepseek-chat", tavily_key: "" },
  pollErrors: 0,
  activeJobId: null,
  saveFolder: "",
  permGranted: false,
  projects: [],
  currentProjectId: null,
  generateMessages: [],
  reviseMessages: [],
  paper: "",
  topic: "",
  requirementsText: "",
  requirementsName: "",
  reviseDocText: "",
  reviseDocName: "",
  lastSavedPath: "",
  isGenerating: false,
  pollTimer: null,
  defaults: null,
  exportFormat: {
    font_family: "times",
    font_size: 12,
    line_spacing: 1.5,
    margin_inches: 1.25,
  },
};

const $ = (s) => document.querySelector(s);
const $$ = (s) => document.querySelectorAll(s);

function uid() {
  return "p_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function esc(s) {
  const d = document.createElement("div");
  d.textContent = s;
  return d.innerHTML;
}

function showFatal(msg) {
  const el = document.getElementById("joekuFatal");
  if (el) {
    el.textContent = String(msg);
    el.classList.add("show");
  }
  console.error(msg);
}

// --- Storage ---
function loadStorage() {
  try {
    const cfg = localStorage.getItem(STORAGE.config);
    if (cfg) state.config = { ...state.config, ...JSON.parse(cfg) };
  } catch (_) {}
  state.saveFolder = localStorage.getItem(STORAGE.folder) || "";
  state.permGranted = localStorage.getItem(STORAGE.perm) === "1";
  state.config.tavily_key = localStorage.getItem(STORAGE.tavily) || state.config.tavily_key || "";
  try {
    const fmt = localStorage.getItem(STORAGE.exportFormat);
    if (fmt) state.exportFormat = { ...state.exportFormat, ...JSON.parse(fmt) };
  } catch (_) {}
  try {
    state.projects = JSON.parse(localStorage.getItem(STORAGE.projects) || "[]");
  } catch (_) {
    state.projects = [];
  }
  if (!state.projects.length) {
    const id = uid();
    const chatId = uid();
    state.projects = [{
      id,
      name: "默认项目",
      chats: [{ id: chatId, title: "新对话", generateMessages: [], paper: "", topic: "", lastSavedPath: "", updatedAt: Date.now() }],
      currentChatId: chatId,
      generateMessages: [],
      reviseMessages: [],
      paper: "",
      topic: "",
      lastSavedPath: "",
      createdAt: Date.now(),
    }];
  }
  migrateProjectsChats();
  const cur = localStorage.getItem(STORAGE.currentProject);
  state.currentProjectId = state.projects.some((p) => p.id === cur) ? cur : state.projects[0].id;
  loadCurrentProjectData();
}

function saveConfig() {
  localStorage.setItem(STORAGE.config, JSON.stringify(state.config));
  if (state.config.tavily_key) localStorage.setItem(STORAGE.tavily, state.config.tavily_key);
}

function saveProjects() {
  persistCurrentProject();
  localStorage.setItem(STORAGE.projects, JSON.stringify(state.projects));
  localStorage.setItem(STORAGE.currentProject, state.currentProjectId);
}

function migrateProjectsChats() {
  state.projects.forEach((p) => {
    if (p.chats?.length) return;
    const chatId = uid();
    p.chats = [{
      id: chatId,
      title: chatTitleFromMessages(p.generateMessages, p.topic),
      generateMessages: p.generateMessages || [],
      paper: p.paper || "",
      topic: p.topic || "",
      lastSavedPath: p.lastSavedPath || "",
      updatedAt: Date.now(),
    }];
    p.currentChatId = chatId;
  });
}

function chatTitleFromMessages(msgs, topic) {
  const first = (msgs || []).find((m) => m.role === "user" && m.content?.trim());
  const raw = first?.content?.trim() || topic?.trim() || "新对话";
  return raw.length > 28 ? `${raw.slice(0, 28)}…` : raw;
}

function currentProject() {
  return state.projects.find((p) => p.id === state.currentProjectId) || state.projects[0];
}

function currentChat() {
  const p = currentProject();
  if (!p?.chats?.length) return null;
  return p.chats.find((c) => c.id === p.currentChatId) || p.chats[0];
}

function loadCurrentProjectData() {
  const p = currentProject();
  const chat = currentChat();
  state.reviseMessages = p.reviseMessages ? [...p.reviseMessages] : [];
  if (chat) {
    state.generateMessages = chat.generateMessages ? [...chat.generateMessages] : [];
    state.paper = chat.paper || "";
    state.topic = chat.topic || "";
    state.lastSavedPath = chat.lastSavedPath || "";
    p.currentChatId = chat.id;
  } else {
    state.generateMessages = p.generateMessages ? [...p.generateMessages] : [];
    state.paper = p.paper || "";
    state.topic = p.topic || "";
    state.lastSavedPath = p.lastSavedPath || "";
  }
}

function persistCurrentProject() {
  const p = currentProject();
  if (!p) return;
  p.reviseMessages = state.reviseMessages;
  const chat = currentChat();
  if (chat) {
    chat.generateMessages = state.generateMessages;
    chat.paper = state.paper;
    chat.topic = state.topic;
    chat.lastSavedPath = state.lastSavedPath;
    chat.updatedAt = Date.now();
    chat.title = chatTitleFromMessages(chat.generateMessages, chat.topic);
  } else {
    p.generateMessages = state.generateMessages;
    p.paper = state.paper;
    p.topic = state.topic;
    p.lastSavedPath = state.lastSavedPath;
  }
}

// --- Projects ---
function renderProjectList() {
  const el = $("#projectList");
  if (!el) return;
  el.innerHTML = "";
  state.projects.forEach((p) => {
    const li = document.createElement("li");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "project-item" + (p.id === state.currentProjectId ? " active" : "");
    btn.textContent = p.name;
    btn.addEventListener("click", () => switchProject(p.id));
    btn.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      if (state.projects.length <= 1) {
        alert("至少保留一个项目");
        return;
      }
      if (confirm(`删除项目「${p.name}」及其对话记录？`)) deleteProject(p.id);
    });
    li.appendChild(btn);
    el.appendChild(li);
  });
}

function switchProject(id) {
  persistCurrentProject();
  state.currentProjectId = id;
  loadCurrentProjectData();
  saveProjects();
  renderProjectList();
  renderChatList();
  renderThread("generate");
  renderThread("revise");
  renderDocPreview();
  setDocOpenLayout(!!state.paper);
  clearPendingReq();
}

function createProject() {
  const name = prompt("项目名称", "新项目");
  if (!name?.trim()) return;
  persistCurrentProject();
  const id = uid();
  const chatId = uid();
  state.projects.unshift({
    id,
    name: name.trim(),
    chats: [{ id: chatId, title: "新对话", generateMessages: [], paper: "", topic: "", lastSavedPath: "", updatedAt: Date.now() }],
    currentChatId: chatId,
    generateMessages: [],
    reviseMessages: [],
    paper: "",
    topic: "",
    lastSavedPath: "",
    createdAt: Date.now(),
  });
  switchProject(id);
}

function renderChatList() {
  const el = $("#chatList");
  if (!el) return;
  const p = currentProject();
  el.innerHTML = "";
  const chats = [...(p.chats || [])].sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  chats.forEach((c) => {
    const li = document.createElement("li");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "chat-item" + (c.id === p.currentChatId ? " active" : "");
    btn.textContent = c.title || "新对话";
    btn.title = c.title || "新对话";
    btn.addEventListener("click", () => switchChat(c.id));
    btn.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      if ((p.chats || []).length <= 1) {
        alert("至少保留一条对话");
        return;
      }
      if (confirm(`删除对话「${c.title || "新对话"}」？`)) deleteChat(c.id);
    });
    li.appendChild(btn);
    el.appendChild(li);
  });
}

function switchChat(chatId) {
  persistCurrentProject();
  const p = currentProject();
  p.currentChatId = chatId;
  loadCurrentProjectData();
  saveProjects();
  renderChatList();
  renderThread("generate");
  renderDocPreview();
  setDocOpenLayout(!!state.paper);
  clearPendingReq();
}

function createChat() {
  if (state.isGenerating) {
    if (!confirm("论文正在生成中。新建对话不会停止当前任务，确定继续？")) return;
  }
  persistCurrentProject();
  const p = currentProject();
  const id = uid();
  const chat = { id, title: "新对话", generateMessages: [], paper: "", topic: "", lastSavedPath: "", updatedAt: Date.now() };
  p.chats = p.chats || [];
  p.chats.unshift(chat);
  p.currentChatId = id;
  state.generateMessages = [];
  state.paper = "";
  state.topic = "";
  state.lastSavedPath = "";
  saveProjects();
  renderChatList();
  renderThread("generate");
  renderDocPreview();
  setDocOpenLayout(false);
  setDocCollapsed(false);
  clearPendingReq();
  const composerInput = $("#composerInput");
  if (composerInput) composerInput.value = "";
  const btn = $("#newChatBtn");
  btn?.classList.remove("glass-pressed");
  btn?.blur();
  requestAnimationFrame(() => {
    const input = $("#composerInput");
    if (input) input.focus();
  });
}

function deleteChat(chatId) {
  const p = currentProject();
  p.chats = (p.chats || []).filter((c) => c.id !== chatId);
  if (p.currentChatId === chatId) p.currentChatId = p.chats[0]?.id;
  loadCurrentProjectData();
  saveProjects();
  renderChatList();
  renderThread("generate");
  renderDocPreview();
  setDocOpenLayout(!!state.paper);
}

function deleteProject(id) {
  state.projects = state.projects.filter((p) => p.id !== id);
  if (state.currentProjectId === id) state.currentProjectId = state.projects[0].id;
  loadCurrentProjectData();
  saveProjects();
  renderProjectList();
  renderThread("generate");
  renderThread("revise");
  renderDocPreview();
}

// --- API ---
function llmHeaders() {
  const h = {
    "Content-Type": "application/json",
    "X-API-Key": state.config.api_key,
    "X-Base-Url": state.config.base_url,
    "X-Model": state.config.model,
  };
  if (state.config.tavily_key) h["X-Tavily-Key"] = state.config.tavily_key;
  return h;
}

async function readApiResponse(res) {
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.detail || data.message || res.statusText);
  return data;
}

async function apiJson(path, opts = {}) {
  const res = await fetch(path, { ...opts, headers: { ...llmHeaders(), ...(opts.headers || {}) } });
  return readApiResponse(res);
}

// --- Auth / settings ---
function updateSidebarStatus() {
  const el = $("#sidebarStatus");
  if (!el) return;
  if (state.loggedIn) {
    el.textContent = state.config.model || "已连接";
    el.classList.add("on");
  } else {
    el.textContent = "未登录";
    el.classList.remove("on");
  }
}

function fillSettingsForm() {
  $("#apiKeyInput").value = state.config.api_key;
  $("#baseUrlInput").value = state.config.base_url;
  const mi = $("#modelInput");
  const model = state.config.model || "deepseek-chat";
  if (mi?.options?.length) {
    const has = [...mi.options].some((o) => o.value === model);
    mi.value = has ? model : "deepseek-chat";
  }
  $("#tavilyKeyInput").value = state.config.tavily_key || "";
}

function fillLoginForm() {
  $("#loginApiKey").value = state.config.api_key || "";
  $("#loginBaseUrl").value = state.config.base_url || "https://api.deepseek.com/v1";
  const sel = $("#loginModel");
  const model = state.config.model || "deepseek-chat";
  if (sel) {
    const has = [...sel.options].some((o) => o.value === model);
    sel.value = has ? model : "deepseek-chat";
  }
}

function setLoginStatus(msg, type = "") {
  const el = $("#loginStatus");
  if (!el) return;
  el.textContent = msg || "";
  el.className = "login-gate-status" + (type ? ` ${type}` : "");
}

async function testConnection(fromLogin = false) {
  const apiKey = (fromLogin ? $("#loginApiKey") : $("#apiKeyInput"))?.value?.trim();
  const baseUrl = (fromLogin ? $("#loginBaseUrl") : $("#baseUrlInput"))?.value?.trim() || "https://api.deepseek.com/v1";
  const model = (fromLogin ? $("#loginModel") : $("#modelInput"))?.value?.trim() || "deepseek-chat";
  const statusEl = fromLogin ? null : $("#settingsResult");

  if (!apiKey) {
    const msg = "请输入 API Key";
    if (fromLogin) setLoginStatus(msg, "err");
    else if (statusEl) statusEl.textContent = msg;
    else alert(msg);
    return false;
  }
  if (fromLogin) setLoginStatus("正在测试连接…");
  else if (statusEl) statusEl.textContent = "正在测试连接…";

  try {
    const res = await fetch("/api/config/test", {
      method: "POST",
      headers: { "Content-Type": "application/json", ...llmHeaders() },
      body: JSON.stringify({ api_key: apiKey, base_url: baseUrl, model }),
    });
    const data = await readApiResponse(res);
    const tavilyKey = $("#tavilyKeyInput")?.value?.trim() || state.config.tavily_key || "";
    state.config = { api_key: apiKey, base_url: baseUrl, model, tavily_key: tavilyKey };
    state.loggedIn = true;
    saveConfig();
    updateSidebarStatus();
    fillSettingsForm();
    if (statusEl) statusEl.textContent = data.message || "连接成功";
    if (fromLogin) {
      setLoginStatus(data.message || "连接成功", "ok");
      closeLoginGate();
      hideLoginBanner();
      setMode("generate");
    }
    return true;
  } catch (e) {
    state.loggedIn = false;
    updateSidebarStatus();
    const msg = "连接失败: " + e.message;
    if (fromLogin) setLoginStatus(msg, "err");
    else if (statusEl) statusEl.textContent = msg;
    else alert(msg);
    return false;
  }
}

function logout() {
  state.config.api_key = "";
  state.loggedIn = false;
  saveConfig();
  updateSidebarStatus();
  $("#settingsResult").textContent = "已退出";
  openLoginGate();
}

function showLoginBanner() {
  let b = $("#loginBanner");
  if (!b) return;
  b.hidden = false;
}

function hideLoginBanner() {
  const b = $("#loginBanner");
  if (b) b.hidden = true;
}

function unlockPage() {
  document.body.removeAttribute("inert");
  document.body.style.pointerEvents = "auto";
  document.querySelectorAll("[inert]").forEach((n) => n.removeAttribute("inert"));
}

function openModal(id) {
  unlockPage();
  const el = document.getElementById(id);
  if (el) el.hidden = false;
}

function closeModal(id) {
  const el = typeof id === "string" ? document.getElementById(id) : id;
  if (el) el.hidden = true;
  unlockPage();
}

function openLoginGate() {
  unlockPage();
  fillLoginForm();
  setLoginStatus("");
  const gate = $("#loginGate");
  if (gate) gate.hidden = false;
}

function closeLoginGate() {
  const gate = $("#loginGate");
  if (gate) gate.hidden = true;
  unlockPage();
}

function requireLogin() {
  if (state.loggedIn && state.config.api_key) return true;
  openLoginGate();
  return false;
}

// --- Mode / layout ---
function setMode(mode) {
  state.mode = mode;
  $$(".rail-btn").forEach((el) => el.classList.toggle("active", el.dataset.mode === mode));
  $$(".workspace").forEach((ws) => ws.classList.toggle("active", ws.dataset.mode === mode));
  $("#workspace-settings")?.classList.toggle("open", mode === "settings");
  if (mode === "settings") fillSettingsForm();
}

function setDocOpenLayout(on) {
  const ws = $("#workspace-generate");
  ws?.classList.toggle("doc-open", on);
  updateDocPanelChrome();
  updateExportButtons();
}

function isDocCollapsed() {
  return $("#workspace-generate")?.classList.contains("doc-collapsed") ?? false;
}

function updateDocPanelChrome() {
  const ws = $("#workspace-generate");
  const collapsed = isDocCollapsed();
  const open = ws?.classList.contains("doc-open") || ws?.classList.contains("generating");
  const tab = $("#docExpandTab");
  const btn = $("#docToggleBtn");
  if (tab) tab.hidden = !(open && collapsed);
  if (btn) {
    btn.textContent = collapsed ? "‹" : "›";
    btn.title = collapsed ? "展开文稿" : "收起文稿";
  }
}

function setDocCollapsed(collapsed) {
  const ws = $("#workspace-generate");
  ws?.classList.toggle("doc-collapsed", collapsed);
  localStorage.setItem(STORAGE.docCollapsed, collapsed ? "1" : "0");
  updateDocPanelChrome();
}

function toggleDocPanel() {
  if (!($("#workspace-generate")?.classList.contains("doc-open") || state.isGenerating)) return;
  setDocCollapsed(!isDocCollapsed());
}

function setGeneratingLayout(on) {
  const ws = $("#workspace-generate");
  ws?.classList.toggle("generating", on);
  state.isGenerating = on;
  const st = $("#docStatus");
  if (st) st.textContent = on ? "生成中…" : state.paper ? "已完成" : "等待生成";
  const input = $("#composerInput");
  if (input) input.placeholder = on ? "生成中，可继续与 Joeku 对话…" : "Message Joeku…";
  if (on) setDocOpenLayout(true);
  updateDocPanelChrome();
}

function updateExportButtons() {
  const has = !!state.paper;
  $("#exportDocxBtn").disabled = !has;
  $("#exportPdfBtn").disabled = !has;
}

function showGenProgress(message, percent) {
  if (!state.isGenerating) return;
  const box = $("#composerProgress");
  if (!box) return;
  box.hidden = false;
  const fill = $("#genProgressFill");
  const text = $("#genProgressText");
  if (fill) fill.style.width = `${percent || 0}%`;
  if (text) text.textContent = message || "";
}

function hideGenProgress() {
  const box = $("#composerProgress");
  if (box) box.hidden = true;
  const fill = $("#genProgressFill");
  if (fill) fill.style.width = "0%";
  const text = $("#genProgressText");
  if (text) text.textContent = "";
}

// --- Thread ---
function threadEl(mode) {
  return mode === "revise" ? $("#thread-revise") : $("#thread-generate");
}

function messagesFor(mode) {
  return mode === "revise" ? state.reviseMessages : state.generateMessages;
}

function normalizeRole(role) {
  if (role === "agent") return "assistant";
  return role;
}

function addTurn(role, content, opts = {}) {
  const mode = opts.mode || state.mode;
  const entry = { role: normalizeRole(role), content, ts: Date.now(), ...opts };
  if (mode === "revise") state.reviseMessages.push(entry);
  else state.generateMessages.push(entry);
  persistCurrentProject();
  saveProjects();
  renderThread(mode);
}

function emptyEl(mode) {
  return mode === "revise" ? $("#emptyRevise") : $("#emptyGenerate");
}

function renderThread(mode) {
  const thread = threadEl(mode);
  if (!thread) return;
  const msgs = messagesFor(mode).filter((m) => !m.progress && m.role !== "system");
  const empty = emptyEl(mode);
  if (empty) empty.hidden = msgs.length > 0;
  thread.innerHTML = "";

  msgs.forEach((m, i) => {
    const role = normalizeRole(m.role);
    const isUser = role === "user";
    const row = document.createElement("div");
    const isNew = i === msgs.length - 1;
    row.className = `msg-row ${isUser ? "user" : "assistant"}${isNew ? " is-new" : ""}`;
    const avatar = document.createElement("div");
    avatar.className = "msg-avatar";
    avatar.textContent = isUser ? "你" : "J";
    const bubble = document.createElement("div");
    bubble.className = "msg-bubble";
    if (isUser) {
      bubble.textContent = m.content;
    } else {
      bubble.innerHTML = m.markdown !== false ? renderMarkdown(m.content) : esc(m.content);
    }
    row.appendChild(avatar);
    row.appendChild(bubble);
    thread.appendChild(row);
  });
  const scroller = thread.closest(".chat-scroll");
  if (scroller) scroller.scrollTo({ top: scroller.scrollHeight, behavior: "smooth" });
}

function updateProgressTurn(message, percent) {
  showGenProgress(message, percent);
}

function clearProgressTurn() {
  hideGenProgress();
}

// --- Doc preview ---
function renderDocPreview() {
  const el = $("#docPreview");
  if (!el) return;
  if (!state.paper) {
    el.innerHTML = '<p class="doc-placeholder">生成开始后，论文将在此实时预览</p>';
    return;
  }
  el.innerHTML = renderMarkdown(state.paper);
  $("#genResult").textContent = state.paper;
  updateExportButtons();
}

// --- Params modal ---
function readExportFormatFromForm() {
  const fmt = {
    font_family: $("#genFontFamily")?.value || "times",
    font_size: parseInt($("#genFontSize")?.value, 10) || 12,
    line_spacing: parseFloat($("#genLineSpacing")?.value) || 1.5,
    margin_inches: 1.25,
  };
  state.exportFormat = fmt;
  localStorage.setItem(STORAGE.exportFormat, JSON.stringify(fmt));
  return fmt;
}

function applyExportFormatToForm() {
  const f = state.exportFormat;
  if ($("#genFontFamily")) $("#genFontFamily").value = f.font_family || "times";
  if ($("#genFontSize")) $("#genFontSize").value = String(f.font_size || 12);
  if ($("#genLineSpacing")) $("#genLineSpacing").value = String(f.line_spacing || 1.5);
}

function openParamsDialog() {
  const topic =
    $("#composerInput")?.value?.trim() ||
    state.topic ||
    (state.requirementsName ? `根据要求文档：${state.requirementsName}` : "");
  $("#genTopic").value = topic;
  $("#paramsHint").textContent = state.requirementsName
    ? `已上传要求文档「${state.requirementsName}」，请确认参数`
    : "确认以下参数后开始生成";
  $("#saveFolder").value = state.saveFolder;
  applyExportFormatToForm();
  openModal("paramsDialog");
}

function clearPendingReq() {
  state.requirementsText = "";
  state.requirementsName = "";
  $("#attachRow")?.setAttribute("hidden", "");
  $("#reqChip").textContent = "";
}

// --- Generation ---
async function startGeneration(e) {
  e?.preventDefault();
  if (!requireLogin()) return;

  const topic = $("#genTopic")?.value?.trim();
  if (!topic || topic.length < 3) {
    alert("论文主题至少 3 个字符");
    return;
  }

  state.topic = topic;
  const targetWords = parseInt($("#genWords")?.value, 10) || 6000;
  const citationLimit = parseInt($("#genCites")?.value, 10) || 15;

  readExportFormatFromForm();
  closeModal("paramsDialog");
  addTurn("user", topic, { mode: "generate" });
  setGeneratingLayout(true);
  state.paper = "";
  renderDocPreview();
  updateProgressTurn("正在启动生成任务…", 5);

  const body = {
    topic,
    target_words: targetWords,
    search_limit: Math.max(citationLimit, 12),
    citation_limit: citationLimit,
    language: $("#genLanguage")?.value || "zh",
    citation_format: $("#genCitationFormat")?.value || "apa7",
    requirements: state.requirementsText || "",
    fast_mode: false,
    web_search: $("#genWebSearch")?.checked !== false,
    de_ai: $("#genDeAi")?.checked === true,
    deep_quality: $("#genDeepQuality")?.checked === true,
  };

  try {
    const { job_id } = await apiJson("/api/generate/start", { method: "POST", body: JSON.stringify(body) });
    pollGeneration(job_id);
  } catch (err) {
    clearProgressTurn();
    setGeneratingLayout(false);
    addTurn("agent", `生成失败：${err.message}`, { mode: "generate" });
  }
}

const POLL_INTERVAL_MS = 2500;
const MAX_POLL_ERRORS = 60;
const POLL_REQUEST_TIMEOUT_MS = 90000;

async function fetchJobStatus(jobId) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), POLL_REQUEST_TIMEOUT_MS);
  try {
    const res = await fetch(`/api/generate/status/${jobId}`, { signal: ctrl.signal });
    const data = await res.json().catch(() => ({}));
    if (res.status === 404) {
      const err = new Error("任务不存在或已过期");
      err.code = "missing";
      throw err;
    }
    if (!res.ok) throw new Error(data.detail || data.message || res.statusText);
    return data;
  } finally {
    clearTimeout(timer);
  }
}

async function fetchJobResult(jobId) {
  const res = await fetch(`/api/generate/result/${jobId}`);
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.detail || res.statusText);
  return data;
}

function finishGeneration(st, doc) {
  state.paper = doc || state.paper;
  state.topic = st.result?.topic || state.topic;
  localStorage.removeItem(STORAGE.activeJob);
  persistCurrentProject();
  saveProjects();
  renderChatList();
  renderDocPreview();
  clearProgressTurn();
  const wc = st.result?.word_count;
  addTurn("agent", `论文生成完成${wc ? `（约 ${wc} 词）` : ""}。右侧可预览并按所选格式导出。`, {
    mode: "generate",
    markdown: false,
  });
  setGeneratingLayout(false);
  setDocOpenLayout(true);
  clearPendingReq();
  $("#composerInput").value = "";
}

function pollGeneration(jobId) {
  if (state.pollTimer) clearInterval(state.pollTimer);
  state.activeJobId = jobId;
  state.pollErrors = 0;
  localStorage.setItem(STORAGE.activeJob, jobId);

  const tick = async () => {
    try {
      const st = await fetchJobStatus(jobId);
      state.pollErrors = 0;
      if (st.preview) {
        state.paper = st.preview;
        persistCurrentProject();
        renderDocPreview();
        setDocOpenLayout(true);
      }
      if (st.message) updateProgressTurn(st.message, st.percent || 10);

      if (st.status === "done") {
        clearInterval(state.pollTimer);
        state.pollTimer = null;
        state.activeJobId = null;
        let doc = state.paper;
        if (st.result?.has_document) {
          try {
            const full = await fetchJobResult(jobId);
            doc = full.document || doc;
          } catch (e) {
            updateProgressTurn(`获取完整文稿失败，使用预览版本：${e.message}`, 99);
          }
        }
        finishGeneration(st, doc);
        return;
      }
      if (st.status === "error") {
        clearInterval(state.pollTimer);
        state.pollTimer = null;
        state.activeJobId = null;
        localStorage.removeItem(STORAGE.activeJob);
        clearProgressTurn();
        setGeneratingLayout(false);
        addTurn("agent", `生成失败：${st.error || "未知错误"}`, { mode: "generate" });
      }
    } catch (err) {
      if (err.code === "missing" && state.paper) {
        clearInterval(state.pollTimer);
        state.pollTimer = null;
        state.activeJobId = null;
        localStorage.removeItem(STORAGE.activeJob);
        clearProgressTurn();
        setGeneratingLayout(false);
        addTurn("agent", "服务端任务记录已丢失，但预览文稿已保留。可继续导出或重新生成。", {
          mode: "generate",
          markdown: false,
        });
        setDocOpenLayout(true);
        return;
      }
      state.pollErrors += 1;
      updateProgressTurn(`连接中断，重试中 (${state.pollErrors}/${MAX_POLL_ERRORS})…`, 8);
      if (state.pollErrors >= MAX_POLL_ERRORS) {
        clearInterval(state.pollTimer);
        state.pollTimer = null;
        clearProgressTurn();
        setGeneratingLayout(false);
        addTurn("agent", `轮询失败：${err.message}。任务 ID：${jobId}，刷新页面将自动恢复进度。`, {
          mode: "generate",
        });
      }
    }
  };
  tick();
  state.pollTimer = setInterval(tick, POLL_INTERVAL_MS);
}

async function resumeActiveJob() {
  const jobId = localStorage.getItem(STORAGE.activeJob);
  if (!jobId || state.isGenerating) return;
  try {
    const st = await fetchJobStatus(jobId);
    if (st.status === "running" || st.status === "pending") {
      setGeneratingLayout(true);
      updateProgressTurn(`恢复生成任务… ${st.message || ""}`, st.percent || 5);
      pollGeneration(jobId);
    } else if (st.status === "done") {
      localStorage.removeItem(STORAGE.activeJob);
      if (st.result?.has_document) {
        try {
          const full = await fetchJobResult(jobId);
          if (full.document) {
            state.paper = full.document;
            renderDocPreview();
            setDocOpenLayout(true);
          }
        } catch (_) {}
      }
    }
  } catch (_) {
    localStorage.removeItem(STORAGE.activeJob);
  }
}

// --- Chat (during / after generation) ---
async function submitComposerChat(text) {
  const msg = (text || $("#composerInput")?.value || "").trim();
  if (!msg) return;
  addTurn("user", msg, { mode: "generate" });
  $("#composerInput").value = "";
  autoResizeTextarea($("#composerInput"));

  const history = state.generateMessages
    .filter((m) => m.role === "user" || m.role === "assistant")
    .slice(-18)
    .map((m) => ({ role: m.role, content: m.content }));

  try {
    const data = await apiJson("/api/chat", {
      method: "POST",
      body: JSON.stringify({
        messages: history,
        paper_context: state.paper || "",
      }),
    });
    addTurn("assistant", data.reply || "（无回复）", { mode: "generate" });
  } catch (err) {
    addTurn("assistant", `对话失败：${err.message}`, { mode: "generate" });
  }
}

function hasGenerateThread() {
  return state.generateMessages.some((m) => m.role === "user" || m.role === "assistant");
}

// --- Revise ---
async function submitRevise(e) {
  e.preventDefault();
  if (!requireLogin()) return;
  const feedback = $("#reviseInput")?.value?.trim();
  const paper = state.reviseDocText || state.paper;
  if (!feedback) return;

  addTurn("user", feedback, { mode: "revise" });
  $("#reviseInput").value = "";

  if (paper && paper.length >= 50) {
    addTurn("system", "正在分析并生成修改建议…", { mode: "revise" });
    try {
      const data = await apiJson("/api/improve-paper", {
        method: "POST",
        body: JSON.stringify({ paper, feedback }),
      });
      state.reviseMessages = state.reviseMessages.filter((m) => m.role !== "system" || !m.content.includes("正在分析"));
      addTurn("agent", data.document || "（无返回内容）", { mode: "revise" });
    } catch (err) {
      state.reviseMessages = state.reviseMessages.filter((m) => m.role !== "system" || !m.content.includes("正在分析"));
      addTurn("agent", `请求失败：${err.message}`, { mode: "revise" });
    }
  } else {
    try {
      const data = await apiJson("/api/analyze", { method: "POST", body: JSON.stringify({ text: feedback }) });
      addTurn("agent", typeof data.analysis === "string" ? data.analysis : JSON.stringify(data.analysis, null, 2), { mode: "revise" });
    } catch (err) {
      addTurn("agent", `分析失败：${err.message}`, { mode: "revise" });
    }
  }
}

// --- Upload ---
async function uploadFile(file, kind) {
  const fd = new FormData();
  fd.append("file", file);
  const res = await fetch("/api/upload", { method: "POST", body: fd });
  const data = await readApiResponse(res);
  if (kind === "req") {
