/** Lightweight Markdown → HTML for live document preview */
export function renderMarkdown(md) {
  if (!md) return "";
  const esc = (s) =>
    s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  const lines = md.split(/\r?\n/);
  const out = [];
  let inP = false;

  const closeP = () => {
    if (inP) {
      out.push("</p>");
      inP = false;
    }
  };

  for (const raw of lines) {
    const line = raw.trimEnd();
    if (!line.trim()) {
      closeP();
      continue;
    }
    if (line.startsWith("# ")) {
      closeP();
      out.push(`<h1>${inline(esc(line.slice(2)))}</h1>`);
      continue;
    }
    if (line.startsWith("## ")) {
      closeP();
      out.push(`<h2>${inline(esc(line.slice(3)))}</h2>`);
      continue;
    }
    if (line.startsWith("### ")) {
      closeP();
      out.push(`<h3>${inline(esc(line.slice(4)))}</h3>`);
      continue;
    }
    if (line.startsWith("- ") || line.startsWith("* ")) {
      closeP();
      out.push(`<li>${inline(esc(line.slice(2)))}</li>`);
      continue;
    }
    if (!inP) {
      out.push("<p>");
      inP = true;
    } else {
      out.push("<br/>");
    }
    out.push(inline(esc(line)));
  }
  closeP();
  return out.join("");
}

function inline(text) {
  return text
    .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>')
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>")
    .replace(/`([^`]+)`/g, "<code>$1</code>");
}

/* Client-side Markdown → DOCX (Grok-style JS export, no server required) */
import {
  Document,
  Packer,
  Paragraph,
  TextRun,
  HeadingLevel,
  AlignmentType,
} from "https://cdn.jsdelivr.net/npm/docx@8.5.0/+esm";

function stripInline(text) {
  return text
    .replace(/\*\*(.+?)\*\*/g, "$1")
    .replace(/\*(.+?)\*/g, "$1")
    .replace(/`(.+?)`/g, "$1");
}

function inlineRuns(text) {
  const runs = [];
  const pattern = /(\*\*.+?\*\*|\*.+?\*|`[^`]+`)/g;
  let pos = 0;
  let m;
  while ((m = pattern.exec(text)) !== null) {
    if (m.index > pos) runs.push(new TextRun(text.slice(pos, m.index)));
    const token = m[0];
    if (token.startsWith("**")) {
      runs.push(new TextRun({ text: token.slice(2, -2), bold: true }));
    } else if (token.startsWith("*")) {
      runs.push(new TextRun({ text: token.slice(1, -1), italics: true }));
    } else {
      runs.push(new TextRun({ text: token.slice(1, -1), font: "Consolas" }));
    }
    pos = m.index + token.length;
  }
  if (pos < text.length) runs.push(new TextRun(text.slice(pos)));
  return runs.length ? runs : [new TextRun(text)];
}

function mdToParagraphs(markdown, title) {
  const children = [];
  const lines = markdown.split(/\r?\n/);
  let titleUsed = false;

  for (const raw of lines) {
    const line = raw.trimEnd();
    if (!line.trim()) continue;

    if (line.startsWith("# ") && !titleUsed && title) {
      children.push(
        new Paragraph({
          text: title,
          heading: HeadingLevel.TITLE,
          alignment: AlignmentType.CENTER,
        })
      );
      titleUsed = true;
      continue;
    }
    if (line.startsWith("# ")) {
      children.push(new Paragraph({ text: line.slice(2), heading: HeadingLevel.HEADING_1 }));
      continue;
    }
    if (line.startsWith("## ")) {
      children.push(new Paragraph({ text: line.slice(3), heading: HeadingLevel.HEADING_2 }));
      continue;
    }
    if (line.startsWith("### ")) {
      children.push(new Paragraph({ text: line.slice(4), heading: HeadingLevel.HEADING_3 }));
      continue;
    }
    if (line.startsWith("- ") || line.startsWith("* ")) {
      children.push(
        new Paragraph({ children: inlineRuns(line.slice(2)), bullet: { level: 0 } })
      );
      continue;
    }
    if (/^\d+\.\s/.test(line)) {
      children.push(
        new Paragraph({
          children: inlineRuns(line.replace(/^\d+\.\s/, "")),
          numbering: { reference: "default-numbering", level: 0 },
        })
      );
      continue;
    }
    children.push(new Paragraph({ children: inlineRuns(line) }));
  }

  if (!children.length) {
    children.push(new Paragraph({ text: stripInline(markdown) || "(empty)" }));
  }
  return children;
}

export async function downloadDocx(markdown, topic, filename) {
  const safeName = (filename || `${topic || "paper"}.docx`).replace(/[<>:"/\\|?*]/g, "-");
  const name = safeName.toLowerCase().endsWith(".docx") ? safeName : `${safeName}.docx`;

  const doc = new Document({
    numbering: {
      config: [
        {
          reference: "default-numbering",
          levels: [{ level: 0, format: "decimal", text: "%1.", alignment: AlignmentType.START }],
        },
      ],
    },
    sections: [{ children: mdToParagraphs(markdown, topic) }],
  });

  const blob = await Packer.toBlob(doc);
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  a.click();
  URL.revokeObjectURL(url);
  return name;
}

/* Pure black starfield — white stars only */
(function () {
  const canvas = document.getElementById("starfield");
  if (!canvas) return;

  const ctx = canvas.getContext("2d");
  let stars = [];
  let w = 0;
  let h = 0;
  let mouseX = 0.5;
  let mouseY = 0.5;

  function resize() {
    w = canvas.width = window.innerWidth * devicePixelRatio;
    h = canvas.height = window.innerHeight * devicePixelRatio;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
    const count = Math.floor((w * h) / 12000);
    stars = Array.from({ length: count }, () => ({
      x: Math.random() * w,
      y: Math.random() * h,
      z: Math.random() * 1.2 + 0.2,
      r: Math.random() * 1 + 0.2,
      tw: Math.random() * Math.PI * 2,
      spd: Math.random() * 0.12 + 0.03,
    }));
  }

  function draw(t) {
    ctx.fillStyle = "#000000";
    ctx.fillRect(0, 0, w, h);

    const driftX = (mouseX - 0.5) * 10 * devicePixelRatio;
    const driftY = (mouseY - 0.5) * 8 * devicePixelRatio;

    for (const s of stars) {
      s.y += s.spd * s.z * devicePixelRatio;
      s.x += Math.sin(t * 0.0003 + s.tw) * 0.05 * devicePixelRatio;
      if (s.y > h) {
        s.y = 0;
        s.x = Math.random() * w;
      }

      const flicker = 0.35 + Math.sin(t * 0.002 + s.tw) * 0.3;
      const alpha = flicker * s.z * 0.5;
      ctx.fillStyle = `rgba(255,255,255,${alpha})`;
      ctx.beginPath();
      ctx.arc(
        s.x + driftX * s.z * 0.08,
        s.y + driftY * s.z * 0.06,
        s.r * devicePixelRatio,
        0,
        Math.PI * 2
      );
      ctx.fill();
    }

    requestAnimationFrame(draw);
  }

  window.addEventListener("resize", resize);
  window.addEventListener("mousemove", (e) => {
    mouseX = e.clientX / window.innerWidth;
    mouseY = e.clientY / window.innerHeight;
  });

  resize();
  requestAnimationFrame(draw);
})();

/* The Starry Night (1889) — original painting base + slow sky vortex flow */
(function () {
  const canvas = document.createElement("canvas");
  canvas.id = "starryNight";
  document.body.prepend(canvas);
  const ctx = canvas.getContext("2d");

  const BASE_SRC = "/static/starry-night-base.jpg";
  const baseImg = new Image();
  baseImg.crossOrigin = "anonymous";
  baseImg.src = BASE_SRC;

  let W = 0,
    H = 0,
    dpr = 1,
    t0 = performance.now(),
    baseReady = false;

  /* Sky vortex anchors mapped to the painting composition */
  const VORTICES = [
    { nx: 0.2, ny: 0.26, r: 0.19, speed: 0.000022, phase: 0 },
    { nx: 0.52, ny: 0.2, r: 0.17, speed: -0.000018, phase: 1.4 },
    { nx: 0.74, ny: 0.17, r: 0.13, speed: 0.000016, phase: 2.8 },
    { nx: 0.36, ny: 0.44, r: 0.15, speed: 0.000014, phase: 0.9 },
  ];

  const SKY_CLIP = 0.72;

  function resize() {
    dpr = Math.min(devicePixelRatio || 1, 2);
    W = canvas.width = Math.floor(innerWidth * dpr);
    H = canvas.height = Math.floor(innerHeight * dpr);
    canvas.style.width = `${innerWidth}px`;
    canvas.style.height = `${innerHeight}px`;
  }

  function drawPainting() {
    if (!baseReady) {
      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, "#0c1e3a");
      g.addColorStop(1, "#0d1a12");
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
      return;
    }

    const iw = baseImg.naturalWidth;
    const ih = baseImg.naturalHeight;
    const scale = Math.max(W / iw, H / ih);
    const dw = iw * scale;
    const dh = ih * scale;
    const dx = (W - dw) / 2;
    const dy = (H - dh) / 2;
    ctx.drawImage(baseImg, dx, dy, dw, dh);
  }

  function drawVortexFlow(v, time) {
    const cx = v.nx * W;
    const cy = v.ny * H;
    const baseR = v.r * Math.min(W, H);
    const rot = time * v.speed * 100 + v.phase;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rot);
    for (let ring = 0; ring < 10; ring++) {
      ctx.beginPath();
      const rr = baseR * (0.12 + ring * 0.085);
      for (let a = 0; a <= Math.PI * 2; a += 0.03) {
        const wobble =
          Math.sin(a * 3.1 + ring * 0.5 + time * 0.00035) * rr * 0.42 +
          Math.cos(a * 1.7 - time * 0.0002 + v.phase) * rr * 0.18;
        const x = Math.cos(a) * (rr + wobble);
        const y = Math.sin(a) * (rr + wobble) * 0.72;
        if (a === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      const alpha = 0.06 + ring * 0.018;
      const hue = ring % 3;
      const stroke =
        hue === 0
          ? `rgba(28, 72, 128, ${alpha})`
          : hue === 1
            ? `rgba(42, 98, 155, ${alpha})`
            : `rgba(220, 195, 70, ${alpha * 0.55})`;
      ctx.strokeStyle = stroke;
      ctx.lineWidth = (2.2 + ring * 0.35) * dpr;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawStarPulse(time) {
    const stars = [
      { nx: 0.51, ny: 0.19 },
      { nx: 0.34, ny: 0.31 },
      { nx: 0.63, ny: 0.34 },
      { nx: 0.18, ny: 0.4 },
    ];
    for (const s of stars) {
      const sx = s.nx * W;
      const sy = s.ny * H;
      const pulse = 0.55 + Math.sin(time * 0.0012 + s.nx * 12) * 0.25;
      const r = 22 * dpr * pulse;
      const halo = ctx.createRadialGradient(sx, sy, 0, sx, sy, r);
      halo.addColorStop(0, `rgba(255, 244, 180, ${0.22 * pulse})`);
      halo.addColorStop(0.35, `rgba(255, 220, 100, ${0.08 * pulse})`);
      halo.addColorStop(1, "rgba(255,255,255,0)");
      ctx.fillStyle = halo;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function frame(now) {
    const time = now - t0;
    drawPainting();

    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, W, H * SKY_CLIP);
    ctx.clip();
    ctx.globalCompositeOperation = "screen";
    for (const v of VORTICES) drawVortexFlow(v, time);
    drawStarPulse(time);
    ctx.globalCompositeOperation = "source-over";
    ctx.restore();

    requestAnimationFrame(frame);
  }

  baseImg.onload = () => {
    baseReady = true;
  };
  baseImg.onerror = () => {
    baseReady = false;
  };

  addEventListener("resize", resize);
  resize();
  requestAnimationFrame(frame);
})();

/* Joeku v2 — click-safe panels, soft glass (no pseudo overlays, no backdrop-filter on UI) */

:root {
  color-scheme: dark;
  --bg-panel: rgba(32, 36, 48, 0.68);
  --bg-raised: rgba(40, 46, 58, 0.78);
  --bg-input: rgba(12, 14, 20, 0.72);
  --stroke: rgba(255, 255, 255, 0.34);
  --stroke-2: rgba(255, 255, 255, 0.18);
  --edge-hi: rgba(255, 255, 255, 0.38);
  --edge-lo: rgba(0, 0, 0, 0.32);
  --text: #ececec;
  --text-2: #b4b4b4;
  --text-3: #7a7a7a;
  --sans: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --rail-w: 52px;
  --panel-w: 240px;
  --chat-max: 46rem;
  --radius: 16px;
  --radius-sm: 12px;
  --sidebar-radius: 18px;
  --ease: cubic-bezier(0.25, 0.8, 0.25, 1);
