/* Liquid edge — composer & dialogs only (pseudo layers never capture clicks) */
.panel-liquid {
  position: relative;
  overflow: hidden;
  isolation: isolate;
  backdrop-filter: blur(24px) saturate(190%) brightness(1.14);
  -webkit-backdrop-filter: blur(24px) saturate(190%) brightness(1.14);
  border: 1px solid transparent;
  background:
    linear-gradient(rgba(42, 48, 62, 0.84), rgba(42, 48, 62, 0.84)) padding-box,
    linear-gradient(
      100deg,
      rgba(255, 255, 255, 0.62) 0%,
      rgba(255, 255, 255, 0.1) 18%,
      rgba(140, 210, 255, 0.42) 38%,
      rgba(255, 255, 255, 0.08) 58%,
      rgba(255, 255, 255, 0.5) 78%,
      rgba(255, 255, 255, 0.12) 100%
    ) border-box;
  background-size: 100% 100%, 340% 100%;
  animation: liquid-border-flow 20s linear infinite;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.32),
    inset 0 -1px 0 rgba(0, 0, 0, 0.24),
    0 10px 36px rgba(0, 0, 0, 0.28);
}

.panel-liquid::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none !important;
  border-radius: inherit;
  background: linear-gradient(165deg, rgba(255, 255, 255, 0.2) 0%, transparent 48%);
}

.panel-liquid > * {
  position: relative;
  z-index: 2;
  pointer-events: auto;
}

@keyframes liquid-border-flow {
  0% { background-position: 0 0, 0% 0; }
  100% { background-position: 0 0, 340% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .panel-liquid { animation: none; }
}

